export var TR_ALFABE = "abcçdefgğhıijklmnoöprsştuüvyz";
export function sezar(metin, k) {
  var out = "";
  for (var i = 0; i < metin.length; i++) {
    var h = metin[i], j = TR_ALFABE.indexOf(h);
    out += j < 0 ? h : TR_ALFABE[((j + k) % TR_ALFABE.length + TR_ALFABE.length) % TR_ALFABE.length];
  }
  return out;
}
function gurultu(metin) {
  var n = "x#7q@k%z", out = "";
  for (var i = 0; i < metin.length; i++) out += n[i % n.length] + metin[i];
  return out;
}
function ters(s) { return Array.from(s).reverse().join(""); }

